CREATE FUNCTION dg_native_bill_receipt_apply(event_value text,receipt jsonb,ingress_value text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE operation restaurant_financial_operations%ROWTYPE;b restaurant_bills%ROWTYPE;r restaurants%ROWTYPE;previous restaurant_financial_receipts%ROWTYPE;status_value text:=receipt->>'status';sequence_value bigint;payload_hash_value text;action_value text;created text;posting_value text;posted boolean;ignored boolean;failure_code text;
BEGIN
 PERFORM dg_native_reception_runtime(true);PERFORM dg_native_restaurant_fields(receipt,ARRAY['operationId','kind','requestHash','restaurantId','billId','merchantId','amountMinor','currency','remoteOperationId','remoteTransactionId','status','sequence','simulated']);sequence_value:=dg_native_restaurant_integer(receipt->'sequence',1,9007199254740991);
 IF event_value IS NULL OR event_value!~'^[a-f0-9-]{36}$' OR ingress_value IS NULL OR ingress_value NOT IN('worker','callback') OR status_value IS NULL OR status_value NOT IN('pending','succeeded','failed','expired') OR receipt->'simulated' IS DISTINCT FROM 'true'::jsonb THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;
 PERFORM dg_native_bill_transport_lock(receipt->>'operationId');SELECT * INTO operation FROM restaurant_financial_operations WHERE id=receipt->>'operationId';SELECT * INTO b FROM restaurant_bills WHERE id=operation.bill_id;SELECT * INTO r FROM restaurants WHERE id=b.restaurant_id;
 IF operation.id IS NULL OR receipt->>'kind' IS DISTINCT FROM operation.kind OR receipt->>'requestHash' IS DISTINCT FROM operation.request_hash OR receipt->>'restaurantId' IS DISTINCT FROM b.restaurant_id OR receipt->>'billId' IS DISTINCT FROM b.id OR receipt->>'merchantId' IS DISTINCT FROM operation.merchant_id OR dg_native_restaurant_integer(receipt->'amountMinor',1,100000000)<>operation.amount_minor OR receipt->>'currency' IS DISTINCT FROM 'CNY' OR operation.provider_id<>'mock-payments' OR operation.simulated<>1 OR r.environment<>'mock' OR r.app_env IS DISTINCT FROM(SELECT app_env FROM _dg_native_runtime_control WHERE id=1) OR receipt->>'remoteOperationId' IS DISTINCT FROM(CASE WHEN operation.kind='payment' THEN 'mock-pay:' ELSE 'mock-refund:' END)||operation.id OR receipt->>'remoteTransactionId' IS DISTINCT FROM(CASE WHEN operation.kind='payment' THEN 'mock-charge:' ELSE 'mock-refund-tx:' END)||operation.id THEN PERFORM dg_native_bill_error('FINANCIAL_RECEIPT_MISMATCH');END IF;
 IF operation.send_attempts<>1 THEN PERFORM dg_native_bill_error('FINANCIAL_NOT_SENT');END IF;payload_hash_value:=dg_native_office_hash(receipt);SELECT * INTO previous FROM restaurant_financial_receipts WHERE event_id=event_value;
 IF previous.event_id IS NOT NULL THEN IF previous.operation_id<>operation.id OR previous.payload_hash<>payload_hash_value THEN PERFORM dg_native_bill_error('FINANCIAL_EVENT_CONFLICT');END IF;RETURN jsonb_build_object('duplicate',true,'applied',previous.applied=1,'attention',previous.attention=1);END IF;
 action_value:=dg_native_bill_transport_action(operation.id,'bill_receipt',receipt);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;PERFORM dg_native_dining_effect(action_value,'restaurant_financial_receipts',event_value);INSERT INTO restaurant_financial_receipts VALUES(event_value,operation.id,payload_hash_value,receipt::text,status_value,sequence_value,0,0,created);INSERT INTO _dg_native_bill_receipt_origins VALUES(event_value,action_value,(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1),operation.request_hash,payload_hash_value,ingress_value,created);
 posted:=EXISTS(SELECT 1 FROM restaurant_financial_postings WHERE operation_id=operation.id);
 ignored:=status_value<>'succeeded' AND(posted AND operation.error_code IS DISTINCT FROM 'FINANCIAL_RECONCILIATION_REQUIRED' OR status_value='pending' AND operation.status IN('failed','expired','cancelled','stale') OR sequence_value<=operation.last_sequence AND NOT(status_value='pending' AND operation.status='unknown' AND sequence_value=operation.last_sequence));
 IF ignored THEN
  PERFORM dg_native_dining_effect(action_value,'restaurant_financial_operations',operation.id);UPDATE restaurant_financial_operations SET last_sequence=greatest(last_sequence,sequence_value),version=version+1,updated_at=created WHERE id=operation.id;PERFORM dg_native_bill_refresh(action_value,b.id);RETURN jsonb_build_object('duplicate',false,'applied',false,'attention',false);
 END IF;
 -- The verified success and immutable posting survive any later projection failure.
 IF status_value='succeeded' AND NOT posted THEN
  posting_value:=gen_random_uuid()::text;PERFORM dg_native_dining_effect(action_value,'restaurant_financial_postings',posting_value);INSERT INTO restaurant_financial_postings VALUES(posting_value,b.id,operation.id,operation.kind,operation.amount_minor,'CNY',operation.provider_id,operation.merchant_id,receipt->>'remoteTransactionId',r.environment,r.app_env,created);INSERT INTO _dg_native_bill_posting_origins VALUES(posting_value,event_value,operation.id,(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1),action_value);
 END IF;
 IF operation.error_code='FINANCIAL_RECONCILIATION_REQUIRED' AND status_value<>'succeeded' THEN
  PERFORM dg_native_dining_effect(action_value,'restaurant_financial_operations',operation.id);UPDATE restaurant_financial_operations SET status='needs_attention',last_sequence=greatest(last_sequence,sequence_value),lease_token=NULL,lease_until=NULL,lease_action=NULL,next_action=NULL,version=version+1,updated_at=created WHERE id=operation.id;UPDATE restaurant_financial_receipts SET attention=1 WHERE event_id=event_value;PERFORM dg_native_bill_refresh(action_value,b.id);RETURN jsonb_build_object('duplicate',false,'applied',false,'attention',true);
 END IF;
 BEGIN
  PERFORM dg_native_dining_effect(action_value,'restaurant_financial_operations',operation.id);UPDATE restaurant_financial_operations SET status=status_value,remote_operation_id=receipt->>'remoteOperationId',remote_transaction_id=receipt->>'remoteTransactionId',last_sequence=greatest(last_sequence,sequence_value),error_code=CASE WHEN status_value='failed' THEN 'FINANCIAL_VERIFIED_FAILED' END,error_message=CASE WHEN status_value='failed' THEN '模拟渠道明确未完成此资金操作；原收款和退款事实分别保留。' END,lease_token=NULL,lease_until=NULL,lease_action=NULL,next_action=NULL,version=version+1,updated_at=created WHERE id=operation.id;
  UPDATE restaurant_financial_receipts SET applied=1 WHERE event_id=event_value;PERFORM dg_native_bill_refresh(action_value,b.id);PERFORM dg_native_bill_event(action_value,b.id,operation.id,CASE WHEN status_value='succeeded' AND operation.kind='payment' THEN '已核实模拟收款并保留独立资金事实；菜品履行仍单独核对。' WHEN status_value='succeeded' THEN '已核实模拟退款；原收款不覆盖，退款单独登记。' WHEN status_value='pending' THEN '原资金入口已核实接收，尚未核实最终收款或退款。' WHEN status_value='expired' THEN '原收银入口已由可信结果核实关闭或到期。' ELSE '可信渠道明确未完成本次资金操作。' END);
  SET CONSTRAINTS ALL IMMEDIATE;SET CONSTRAINTS ALL DEFERRED;
 EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS failure_code=RETURNED_SQLSTATE;INSERT INTO _dg_native_bill_receipt_failures VALUES(event_value,failure_code,'billing_projection',created);PERFORM dg_native_dining_effect(action_value,'restaurant_financial_operations',operation.id);UPDATE restaurant_financial_operations SET status='needs_attention',last_sequence=greatest(last_sequence,sequence_value),error_code='FINANCIAL_RECONCILIATION_REQUIRED',error_message='可信回执与已核实资金事实已保留，本地投影仍待经理核对；仅查询原事实，不重复资金动作。',lease_token=NULL,lease_until=NULL,lease_action=NULL,next_action=NULL,version=version+1,updated_at=created WHERE id=operation.id;UPDATE restaurant_financial_receipts SET attention=1 WHERE event_id=event_value;PERFORM dg_native_bill_refresh(action_value,b.id);PERFORM dg_native_bill_event(action_value,b.id,operation.id,'可信资金事实已保留，投影异常转经理核对；未伪造结算或抹除原事实。');RETURN jsonb_build_object('duplicate',false,'applied',false,'attention',true);
 END;RETURN jsonb_build_object('duplicate',false,'applied',true,'attention',false);
END;$dg$;

CREATE FUNCTION dg_native_bill_receipt_document(target text,session_value text DEFAULT NULL,token_value text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE meta jsonb;b restaurant_bills%ROWTYPE;t jsonb;
BEGIN
 meta:=dg_native_bill_context('bill',target,session_value,token_value);SELECT * INTO b FROM restaurant_bills WHERE id=target;t:=dg_native_bill_totals(b.id);IF b.status NOT IN('paid','partially_refunded','refunded','void') OR b.settled_at IS NULL OR b.attention_reason IS NOT NULL THEN PERFORM dg_native_bill_error('BILL_NOT_SETTLED');END IF;
 RETURN jsonb_build_object('billId',b.id,'number',b.number,'orderNumber',(SELECT number FROM restaurant_orders WHERE id=b.order_id),'restaurantName',(SELECT name FROM restaurants WHERE id=b.restaurant_id),'currency','CNY','totalMinor',b.amount_minor,'paidMinor',(t->>'paid')::bigint,'refundedMinor',(t->>'refunded')::bigint,'settledAt',b.settled_at,'simulated',true,'notice','明确本地模拟收据，无真实资金往来，不是税务发票。','lines',b.snapshot::jsonb,'transactions',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',posting.id,'kind',posting.kind,'amountMinor',posting.amount_minor,'createdAt',posting.created_at) ORDER BY posting.created_at,posting.id),'[]') FROM restaurant_financial_postings posting WHERE posting.bill_id=b.id));
END;$dg$;
